        "dayOfWeek": 3,
        "schedules" :[
            {
                "startTimeHours": 23,
                "startTimeMinutes": 10,
                "durationMinutes": 100
            }
        ]
    },
    {
        "dayOfWeek": 4,
        "schedules" :[
            {
                "startTimeHours": 10,
                "startTimeMinutes": 10,
                "durationMinutes": 100
            }
        ]
    },
     {
        "dayOfWeek": 5,
        "schedules" :[
            {
